    for _ in range(t):
        n = int(input())
        p = list(map(int, input().split()))
        pos = [0] * (n + 1)
        for idx, val in enumerate(p, 1):
            pos[val] = idx
        result = []
        for m in range(1, n + 1):
            # Get positions of values 1..m
            left = pos[1]
            right = pos[1]
            for v in range(2, m + 1):
                left = min(left, pos[v])
                right = max(right, pos[v])
            # Check if they form a contiguous block of length m
            if right - left + 1 == m:
                result.append('1')
            else:
                result.append('0')
        print(''.join(result))

solve()
