def is_subsequence(s, t):

    # Check if t is a subsequence of s
    i = 0  # index for s
    for char in t:
        while i < len(s) and s[i] != char:
            i += 1
        if i < len(s):
            i += 1  # move to next character in s
        else:
            return False
    return True

def are_anagrams(s, t):
    # Check if s and t are anagrams
    return sorted(s) == sorted(t)

def can_form_with_both(s, t):
    # Check if we can delete from s to get a string with same multiset as t
    # Then we can swap to get t
    # This means we need to have enough of each character
    # Actually, we just need to have the same multiset
    # Because we can delete characters to get exactly the multiset of t,
    # then swap to get the correct order

    # The multiset of t must be a subset of the multiset of s
    from collections import Counter
    cnt_s = Counter(s)
    cnt_t = Counter(t)

    for char, count in cnt_t.items():
        if cnt_s[char] < count:
            return False
    return True

def solve():
    s = input().strip()
    t = input().strip()

    if is_subsequence(s, t):
        print("automaton")
        return
    if are_anagrams(s, t):
        print("array")
        return
    if can_form_with_both(s, t):
        print("both")
        return
    print("need tree")

solve()
"}

