def solve():
    n = int(input())
    guesses = []
    for _ in range(n):
        a, b, c = map(int, input().split())
        guesses.append((a, b, c))

    # Generate all possible 4-digit numbers with distinct digits
    possible_numbers = []
    from itertools import permutations

    for digits in permutations(range(10), 4):
        num = digits[0] * 1000 + digits[1] * 100 + digits[2] * 10 + digits[3]
        possible_numbers.append(num)

    # Check consistency
    consistent = []
    for candidate in possible_numbers:
        valid = True
        for guess in guesses:
            guess_str = str(guess[0])
            candidate_str = str(candidate)

            # Count bulls
            bulls = 0
            used = [False] * 4  # Track which positions are used

            for i in range(4):
                if guess_str[i] == candidate_str[i]:
                    bulls += 1
                    used[i] = True

            # Count cows (digits that are present but in wrong position)
            cows = 0

            for i in range(4):
                if not used[i]:  # Only consider unmatched positions
                    if guess_str[i] in candidate_str:
                        # Check if this digit is used elsewhere
                        found = False
                        for j in range(4):
                            if guess_str[j] == guess_str[i] and j != i:
                                if j < 4 and guess_str[j] == candidate_str[j]:
                                    continue  # This digit is already matched as bull
                                if j < 4 and guess_str[j] in candidate_str and j < 4 and candidate_str[j] != guess_str[i]:
                                    found = True
                                    break

                        if not found:
                            cows += 1

            # Check if matches expected values
            if bulls != guess[1] or cows != guess[2]:
                valid = False
                break

        if valid:
            consistent.append(candidate)

    # Analyze results
    if len(consistent) == 1:
        print(str(consistent[0]).zfill(4))
    elif len(consistent) == 0:
        print("Incorrect data")
    else:
        print("Need more data")

solve()
