import sys
from heapq import heappush, heappop

def solve():
    n, s, k = map(int, sys.stdin.readline().split())
    r = list(map(int, sys.stdin.readline().split()))
    colors = sys.stdin.readline().strip()

    # State: (pos, last_color, last_amount, total, time)
    # last_color: 0=none (first), 1=R, 2=G, 3=B
    # 0-indexed positions

    # Priority queue: (time, pos, last_color, last_amount, total)
    pq = [(0, s - 1, 0, 0, 0)]
    visited = set()

    while pq:
        time, pos, last_color, last_amount, total = heappop(pq)

        if total >= k:
            print(time)
            return

        state = (pos, last_color, last_amount, total)
        if state in visited:
            continue
        visited.add(state)

        # Try moving
        for move in [-1, 1]:
            if 0 <= pos + move < n:
                new_pos = pos + move
                heappush(pq, (time + 1, new_pos, last_color, last_amount, total))

        # Try eating if valid
        if total + r[pos] <= k:
            new_total = total + r[pos]
            new_color = ord(colors[pos]) - ord('R') + 1
            if last_color == 0 or new_color != last_color:
                # First eat
                if last_amount == 0:
                    heappush(pq, (time, new_pos, new_color, r[pos], new_total))
                else:
                    # Not first, need strictly more candies
                    if r[pos] > last_amount:
                        heappush(pq, (time, new_pos, new_color, r[pos], new_total))

    print(-1)

if __name__ == "__main__":
    solve()
"}

