import sys

def fits(w1, h1, w2, h2, a, b):
    """Check if two rectangles of size w1×h1 and w2×h2 can fit on a paper of size a×b"""
    # Check side by side horizontally
    if max(w1, w2) <= a and (h1 + h2) <= b:
        return True

    # Check side by side vertically
    if max(h1, h2) <= a and (w1 + w2) <= b:
        return True

    # Check stacked
    if max(w1, w2) <= a and max(h1, h2) <= b:
        return True

    return False

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    n = int(data[0])
    a = int(data[1])
    b = int(data[2])

    seals = []
    index = 3
    for _ in range(n):
        w = int(data[index])
        h = int(data[index + 1])
        index += 2
        # Consider both orientations
        seals.append((w, h))
        seals.append((h, w))

    # Try all pairs of different original seals
    max_area = 0
    for i in range(n):
        for j in range(i + 1, n):
            # Check all orientations for seal i
            for orient1 in [(seals[2*i][0], seals[2*i][1]), (seals[2*i][1], seals[2*i][0])]:
                # Check all orientations for seal j
                for orient2 in [(seals[2*j][0], seals[2*j][1]), (seals[2*j][1], seals[2*j][0])]:
                    if fits(orient1[0], orient1[1], orient2[0], orient2[1], a, b):
                        area = orient1[0] * orient1[1] + orient2[0] * orient2[1]
                        max_area = max(max_area, area)

    print(max_area)

if __name__ == "__main__":
    solve()
"}

