            matrix[i][j] = 0
        elif i % 2 == 0:
            # Even row
            if j == 0:
                matrix[i][j] = 0
            elif j == i + 1:
                matrix[i][j] = i
            elif j == i - 1:
                matrix[i][j] = n - 1
