def find_longest_regular_bracket_sequence(s):
    stack = []
    max_len = 0
    count = 0

    balance = 0

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
            balance += 1
        else:  # char == ')'
            if stack:
                # There's a matching opening parenthesis
                start = stack.pop()
                current_len = i - start + 1

                # Check if this is the first valid substring
                if current_len > max_len:
                    max_len = current_len
                    count = 1
                elif current_len == max_len:
                    count += 1
                balance = 0

    if max_len == 0:
        print("0 1")
    else:
        print(max_len, count)

# Read input and output result
