def max_points(n, a):
    # This is a greedy approach
    # Sort the elements by value
    elements = sorted([(value, i) for i, value in enumerate(a)], key=lambda x: -x[0])

    # Use a set to track which elements are still present
    present = [True] * n

    total = 0

    for value, i in elements:
        if not present[i]:
            continue

        # Eliminate this element
        total += value
        present[i] = False

        # Eliminate elements equal to value - 1
        for j in range(n):
            if j == i or not present[j]:
                continue
            if a[j] == value - 1:
                total += a[j]
                present[j] = False

        # Eliminate elements equal to value + 1
        for j in range(n):
            if j == i or not present[j]:
                continue
            if a[j] == value + 1:
                total += a[j]
                present[j] = False

    return total

n = int(input())
a = list(map(int, input().split()))
print(max_points(n, a))
