def compute_square_free_part(x, spf):
    square_free = 1
    while x > 1:
        p = spf[x]
        count = 0
        while x % p == 0:
            x //= p
            count += 1
        if count % 2 == 1:
            square_free *= p
    return square_free

def solve():
    # Precompute smallest prime factors up to 10^7
    max_val = 10**7
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val**0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))

        # Compute square-free parts
        square_free = []
        for num in a:
            sq = compute_square_free_part(num, spf)
            square_free.append(sq)

        # Greedy algorithm to minimize segments
        segments = 1
        curr_segment = set()

        for sf in square_free:
            if sf in curr_segment:
                segments += 1
                curr_segment = {sf}  # Start new segment with this number
            else:
                curr_segment.add(sf)

        print(segments)

