def find_kth_element(k):
    s = set()
    i = 1
    while True:
        # Try to add triplet (i, 2i, 3i)
        if i not in s and 2 * i not in s and 3 * i not in s:
            s.add(i)
            s.add(2 * i)
            s.add(3 * i)

            # Check if we've found the k-th element
            if len(s) == k:
                return i

        i += 1

