def longest_common_prefix(a, b):
    """Return length of longest common prefix between two strings."""
    min_len = min(len(a), len(b))
    count = 0
    while count < min_len and a[count] == b[count]:
        count += 1
    return count


def hungarian(matrix, n):
    """Hungarian Algorithm for maximum weight perfect matching in bipartite graph.
    Returns: (max_weight, matching)
    matching[i] = j means student i matches pseudonym j."""
    INF = float('inf')
    n = len(matrix)

    # Costs matrix (we convert to minimum cost by subtracting from max possible weight)
    max_possible = max(max(row) for row in matrix)
    cost = [[max_possible - matrix[i][j] for j in range(n)] for i in range(n)]

    # Matchings
    match_to = [-1] * n  # match_to[i] = j means pseudonym i is matched to student j

    # Reduce rows
    for i in range(n):
        min_row = min(cost[i])
        for j in range(n):
            cost[i][j] -= min_row

    # Reduce columns
    for j in range(n):
        min_col = min(cost[i][j] for i in range(n))
        for i in range(n):
            cost[i][j] -= min_col

    # Cover all zeros with minimum lines
    cover = [0] * n
    for i in range(n):
        for j in range(n):
            if cost[i][j] == 0:
                cover[i] = 1
                break

    # Find uncovered row with zero (no zeros found yet, continue)
    while True:
        found = False
        for i in range(n):
            if cover[i]:
                continue
            for j in range(n):
                if cost[i][j] == 0:
                    cover[i] = 1
                    found = True
                    break
            if found:
                break
        if not found:
            break

    # Find column with zero in uncovered row
    for i in range(n):
        if cover[i]:
            continue
        for j in range(n):
            if cost[i][j] == 0:
                found = True
                break

    # Minimum uncovered element
    min_uncovered = INF
    for i in range(n):
        for j in range(n):
            if cover[i]:
                continue
            min_uncovered = min(min_uncovered, cost[i][j])

    # Subtract from uncovered rows, add to covered columns
    for i in range(n):
        if cover[i]:
            continue
        for j in range(n):
            if cost[i][j] == 0:
                cover[i] = 1
                found = True
            else:
                cost[i][j] -= min_uncovered

    # Add min_uncovered to covered columns
    for i in range(n):
        if cover[i]:
            continue
        for j in range(n):
            if cost[i][j] == 0:
                cover[i] = 1
                found = True
            else:
                cost[i][j] += min_uncovered

    # Find a matching
    for i in range(n):
        for j in range(n):
            if cost[i][j] == 0:
                # Try to augment
                if match_to[j] == -1:
                    match_to[j] = i
                else:
                    # Follow path
                    u = match_to[j]
                    while u != -1:
                        match_to[j] = u
                        u = match_to[u]
                    match_to[j] = i

    return (max_possible * n - sum(sum(row) for row in cost), match_to)


