def is_subsequence(sub, superseq):
    """Check if sub is a subsequence of superseq."""
    it = iter(superseq)
    return all(c in it for c in sub)

def solve():
    q = int(input())
    for _ in range(q):
        s = input().strip()
        t = input().strip()
        p = input().strip()

        # Check if s is a subsequence of t
        if not is_subsequence(s, t):
            print("NO")
            continue

        # Count characters in t that are not in s
        t_count = {}
        s_set = set(s)
        for c in t:
            if c not in s_set:
                t_count[c] = t_count.get(c, 0) + 1

        # Count characters in p
        p_count = {}
        for c in p:
            p_count[c] = p_count.get(c, 0) + 1

        # Check if we have enough of each character
        possible = True
        for c, needed in t_count.items():
            if p_count.get(c, 0) < needed:
                possible = False
                break

