    operations = 0
    i = 0
    while i < len(a):
        if a[i] != x:
            # Found a segment of non-x elements
            while i < len(a) and a[i] != x:
                i += 1
            operations += 1
        else:
            i += 1
    return operations

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        # Find the element that minimizes operations
        freq = {}
        for val in a:
            freq[val] = freq.get(val, 0) + 1
        # Try all elements
        min_ops = float('inf')
        for val in freq:
            ops = count_operations(a, val)
            min_ops = min(min_ops, ops)
        out_lines.append(str(min_ops))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

