    for i in range(4):
        if secret_digits[i] == guess_digits[i]:
            bull_count += 1

    if bull_count != bulls:
        return False

    # Count cows
    guess_remaining = guess_digits[:]
    for i in range(4):
        if secret_digits[i] == guess_digits[i]:
            guess_remaining[i] = None

    cow_count = 0
    for i in range(4):
        if guess_remaining[i] is not None:
            for j in range(4):
                if secret_digits[j] == guess_digits[i]:
                    cow_count += 1
                    secret_digits[j] = None
                    guess_remaining[i] = None
                    break

    return cow_count == cows


