def solve():
    n, s, k = map(int, input().split())
    r = list(map(int, input().split()))
    c = input().strip()

    # DP: dp[pos][last_color][last_count][total] = min_time
    INF = float('inf')
    dp = [ [ [ [INF] * (k + 1) for _ in range(51) ] for _ in range(3) ] for _ in range(n + 1) ]

    # Position is 1-indexed
    for i in range(n):
        dp[i + 1][0][0][0] = 0  # 0 for no color yet, 0 for candies count, 0 for total eaten

    # Convert colors to 0, 1, 2 for DP
    for i in range(n):
        color = 0
        if c[i] == 'R':
            color = 1
        elif c[i] == 'G':
            color = 2

    # DP transitions
    for pos in range(1, n + 1):
        for last_color in range(3):
            for last_count in range(51):
                for total in range(k + 1):
                    if dp[pos][last_color][last_count][total] == INF:
                        continue

                    # Try to eat candies from current box if possible
                    current_color = 0
                    if c[pos - 1] == 'R':
                        current_color = 1
                    elif c[pos - 1] == 'G':
                        current_color = 2

                    if last_color != current_color and last_count < r[pos - 1] and total + r[pos - 1] <= k:
                        new_total = total + r[pos - 1]
                        dp[pos][current_color][r[pos - 1]][new_total] = min(
                            dp[pos][current_color][r[pos - 1]][new_total],
                            dp[pos][last_color][last_count][total]
                        )

                    # Try to move left or right
                    for delta in [-1, 1]:
                        new_pos = pos + delta
                        if 1 <= new_pos <= n:
                            dp[new_pos][last_color][last_count][total] = min(
                                dp[new_pos][last_color][last_count][total],
                                dp[pos][last_color][last_count][total] + 1
                            )

    # Find minimum time to eat at least k candies
    answer = INF
    for pos in range(1, n + 1):
        for last_color in range(3):
            for last_count in range(51):
                for total in range(k + 1):
                    if total >= k:
                        answer = min(answer, dp[pos][last_color][last_count][total])

    if answer == INF:
        print(-1)
    else:
        print(answer)

solve()
