MOD = 1000000007

n, m = map(int, input().split())

# buses: key = (s, t) where s < t
buses = set()

for _ in range(m):
    s, t = map(int, input().split())
    buses.add((s, t))

# dp[i] = number of ways to reach stop i
dp = {}
dp[0] = 1

# Track which stops have buses ending at them
end_points = {}

# For each stop that has buses ending at it, store the list of start stops
start_for_end = {}

for s, t in buses:
    if t not in end_points:
        end_points[t] = 0
        start_for_end[t] = []
    end_points[t] += 1
    start_for_end[t].append(s)

# Sort stops with buses
stops_with_buses = sorted([0] + [s for s, t in buses] + [t for s, t in buses])

# Process stops in order
dp_sorted = [0] * len(stops_with_buses)
dp_sorted[0] = dp[0]

for i, stop in enumerate(stops_with_buses):
    if stop == 0:
        continue

    if stop in end_points:
        # Sum dp of all start stops that have buses ending at stop
        total = 0
        for s in start_for_end[stop]:
            if s in dp:
                total += dp[s]
                total %= MOD
        dp[stop] = total

    # Update dp_sorted
    if i < len(dp_sorted):
        dp_sorted[i] = dp[stop]
    else:
        dp_sorted.append(dp[stop])

# Now compute final answer
# We need dp[n] if n is a stop that has buses
if n in dp:
    print(dp[n] % MOD)
else:
    print(0)
