def solve():
    n, k = map(int, input().split())
    s = input().strip()

    # Memoization dictionary: (pos, diff) -> best sequence
    memo = {}

    def dfs(pos, diff, path):
        # Base case: we've processed all characters
        if pos == n:
            # Check if we reached exactly k
            if abs(diff) == k:
                return path
            return None

        # Check memoization
        key = (pos, diff)
        if key in memo:
            return memo[key]

        result = None

        # Try each possibility for the current character
        for next_char in ['W', 'L', 'D']:
            if s[pos] != '?' and s[pos] != next_char:
                continue  # Skip if character is fixed

            # Compute new difference
            if next_char == 'W':
                new_diff = diff + 1
            elif next_char == 'L':
                new_diff = diff - 1
            else:  # 'D'
                new_diff = diff

            # Check if we reached k before the end
            if abs(new_diff) == k and pos != n - 1:
                continue

            # Recursively try next character
            sub_result = dfs(pos + 1, new_diff, path + next_char)
            if sub_result is not None:
                result = sub_result
                break

        memo[key] = result
        return result

    answer = dfs(0, 0, '')
    if answer is not None:
        print(answer)
    else:
        print("NO")

solve()
