def count_valid_decks(n, k, a):
    # For each position, we'll track remainders of products ending at that position
    # remainder_map[i] stores a list of (remainder, count) pairs for products ending at position i

    # We need to count intervals [i, j] where product % k == 0

    remainder_map = []

    for j in range(n):
        # Products ending at position j
        current_map = []

        # Product of single element a[j]
        rem = a[j] % k
        if rem == 0:
            current_map.append((0, 1))  # Product divisible by k
        else:
            current_map.append((rem, 1))

        # Products ending at j that start somewhere before
        for i in range(j):
            prev_rem, prev_count = remainder_map[i]
            new_rem = (prev_rem * a[j]) % k
            if new_rem == 0:
                current_map.append((0, prev_count))
            else:
                current_map.append((new_rem, prev_count))

        remainder_map.append(current_map)

    # Count all intervals where product % k == 0
    total = 0
    for i in range(n):
        for rem, count in remainder_map[i]:
            if rem == 0:
                total += count

    return total

