def square_free_part(x):
    """Return the square-free part of x"""
    # Factorize x and keep primes with odd exponents

    square_free = 1

    # Check divisibility by 2
    if x % 2 == 0:
        cnt = 0
        while x % 2 == 0:
            x //= 2
            cnt += 1
        if cnt % 2 == 1:
            square_free *= 2

    # Check odd numbers up to sqrt(x)
    i = 3
    while i * i <= x:
        if x % i == 0:
            cnt = 0
            while x % i == 0:
                x //= i
                cnt += 1
            if cnt % 2 == 1:
                square_free *= i
        i += 2

    # If x > 1, it's a prime factor
    if x > 1:
        square_free *= x

    return square_free

def solve():
    t = int(input())

    for _ in range(t):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))

        # Compute square-free parts
        square_frees = []
        for num in a:
            square_frees.append(square_free_part(num))

        # Count distinct square-free parts
        distinct = len(set(square_frees))
        print(distinct)

