from collections import Counter

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    points = []
    for _ in range(n):
        x = int(next(it))
        y = int(next(it))
        points.append((x, y))

    # For each pair, compute (x1+x2, y1+y2)
    cnt = Counter()
    for i in range(n):
        for j in range(i+1, n):
            x1, y1 = points[i]
            x2, y2 = points[j]
            key = (x1 + x2, y1 + y2)
            cnt[key] += 1

    res = 0
    for v in cnt.values():
        if v >= 2:
            res += v * (v - 1) // 2

    print(res)

if __name__ == "__main__":
    solve()
