import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    # Parse n and m
    idx = 0
    n = int(data[idx])
    m = int(data[idx+1])
    idx += 2

    # Group strings by length
    strings_by_length = {}
    for _ in range(n):
        s = data[idx]
        idx += 1
        l = len(s)
        if l not in strings_by_length:
            strings_by_length[l] = []
        strings_by_length[l].append(s)

    # Process queries
    out_lines = []
    for _ in range(m):
        q = data[idx]
        idx += 1
        l = len(q)
        if l not in strings_by_length:
            out_lines.append("NO")
            continue

        found = False
        for s in strings_by_length[l]:
            diff = 0
            for ch1, ch2 in zip(q, s):
                if ch1 != ch2:
                    diff += 1
                    if diff > 1:
                        break
            if diff == 1:
                found = True
                break

        out_lines.append("YES" if found else "NO")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
