import sys

def count_parallelograms(points):
    midpoint_count = {}
    n = len(points)

    for i in range(n):
        x1, y1 = points[i]
        for j in range(i + 1, n):
            x2, y2 = points[j]
            mid_x = (x1 + x2) / 2
            mid_y = (y1 + y2) / 2

            # Use a tuple of floats as the key
            key = (mid_x, mid_y)

            if key in midpoint_count:
                midpoint_count[key] += 1
            else:
                midpoint_count[key] = 1

    # Count parallelograms
    parallelograms = 0
