def count_ways(n, k, arr):
    # Edge case: if k is 1, all subarrays are valid
    if k == 1:
        return n * (n + 1) // 2

    # Factorize k
    prime_factors = {}
    temp = k
    i = 2
    while i * i <= temp:
        while temp % i == 0:
            prime_factors[i] = prime_factors.get(i, 0) + 1
            temp //= i
        i += 1
    if temp > 1:
        prime_factors[temp] = prime_factors.get(temp, 0) + 1

    # Prime factor list
    primes = list(prime_factors.items())
    if not primes:
        return 0

    # For each position, compute how many of each prime factor we have in prefix
    prefix_counts = [{} for _ in range(n)]
    prefix_counts[0] = {}

    for i in range(1, n):
        prefix_counts[i] = prefix_counts[i-1].copy()
        num = arr[i]
        temp = num
        for p, cnt in prime_factors.items():
            if temp % p == 0:
                count = 0
                while temp % p == 0:
                    count += 1
                    temp //= p
                prefix_counts[i][p] = count

    # Now for each left, find the minimum right such that the window is valid
    # Then count all subarrays starting at left and ending at any position >= right
    answer = 0

    for left in range(n):
        required = prime_factors.copy()
        current_counts = {}

        for right in range(left, n):
            num = arr[right]
            temp = num
            for p, cnt in prime_factors.items():
                if temp % p == 0:
                    count = 0
                    while temp % p == 0:
                        count += 1
                        temp //= p
                    current_counts[p] = current_counts.get(p, 0) + count

            # Check if window is valid
            valid = True
            for p, cnt in required.items():
                if current_counts.get(p, 0) < cnt:
                    valid = False
                    break

            if valid:
                answer += n - right
                # If window is valid, all subarrays starting at left and ending at any position >= right are valid
                # So we can increment left and continue
                break

    return answer

