    data = sys.stdin.read().split()
    if not data:
        sys.exit()

    n = int(data[0])
    k = int(data[1])
    arr = [int(num) for num in data[2:2+n]]

    result = count_ways(n, k, arr)
    sys.stdout.write(str(result))
