    square_free_part = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            count = 0
            while n % i == 0:
                n //= i
                count += 1
            if count % 2 == 1:
                square_free_part *= i
        i += 1
    if n > 1:
