from collections import defaultdict

def main():
    n = int(input())
    points = []
    for _ in range(n):
        x, y = map(int, input().split())
        points.append((x, y))

    midpoints = defaultdict(int)
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = points[i]
            x2, y2 = points[j]
            mid_x = x1 + x2
            mid_y = y1 + y2
            midpoints[(mid_x, mid_y)] += 1

    ans = 0
    for count in midpoints.values():
        ans += count * (count - 1) // 2

    print(ans)

if __name__ == "__main__":
    main()
