import sys

def solve():
    n = int(sys.stdin.readline())
    points = []
    for _ in range(n):
        x, y = map(int, sys.stdin.readline().split())
        points.append((x, y))

    # Count occurrences of each vector
    vector_count = {}

    # For each pair of points, compute the vector from point1 to point2
    for i in range(n):
        x1, y1 = points[i]
        for j in range(i + 1, n):
            x2, y2 = points[j]
            # Vector from i to j
            vec = (x2 - x1, y2 - y1)

            # Count occurrences of this vector
            if vec in vector_count:
                vector_count[vec] += 1
            else:
                vector_count[vec] = 1

    # Calculate number of parallelograms
    answer = 0
    for count in vector_count.values():
        answer += count * (count - 1) // 2

    # Divide by 2 because each parallelogram is counted twice
    answer //= 2

    print(answer)

if __name__ == "__main__":
    solve()
"}

