n = int(input())

def generate_magic_matrix(n):
    """Generate a magic matrix with n rows and columns"""
    # Construct the matrix
    matrix = []
    for i in range(n):
        row = []
        for j in range(n):
            # A[i][j] = (A[0][j-i % n] + i) % n if j > i
            # A[i][j] = (A[0][j-i % n] + i) % n if j < i
            # A[i][i] = 0

            # Use a simple cyclic pattern
            if i == j:
                row.append(0)
            elif j > i:
                row.append((j - i) % n)
            else:
                row.append((j - i + n) % n)
        matrix.append(row)
    return matrix

def print_matrix(matrix):
    """Print the matrix"""
    for row in matrix:
        print(' '.join(map(str, row)))

def solve():
    n = int(input())
    matrix = generate_magic_matrix(n)
    print_matrix(matrix)

