# Read input
n = int(input())

def generate_magic_matrix(n):
    """Generate a magic matrix with n rows and columns"""
    matrix = []
    for i in range(n):
        row = []
        for j in range(n):
            # Pattern: A[i][j] = (j - i) % n for j > i
            # Pattern: A[i][j] = (i - j) % n for j < i
            # A[i][i] = 0
            if j > i:
                row.append((j - i) % n)
            elif j < i:
                row.append((i - j) % n)
            else:
                row.append(0)
        matrix.append(row)
    return matrix

