# For n=4, we can brute force all subsets of {2, 3, 4}
# And check which subsets allow us to distinguish between 1, 2, 3, 4

from itertools import combinations

numbers = list(range(1, n + 1))

for r in range(n, 0, -1):
    for subset in combinations(numbers, r):
        # Check if this subset works
        works = True
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                # Check if we can distinguish i and j
                # i and j have different answers
                ans_i = [1 if i % y == 0 else 0 for y in subset]
                ans_j = [1 if j % y == 0 else 0 for y in subset]
                if ans_i == ans_j:
                    works = False
                    break
            if not works:
                break
        if works:
            questions = list(subset)
            questions.sort()
            print(len(questions))
            print(' '.join(map(str, questions)))
            break
    if works:
        break
