# Read input
import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    s = data[0]
    q = int(data[1])
    queries = []
    idx = 2
    for _ in range(q):
        li = int(data[idx])
        ri = int(data[idx+1])
        queries.append((li, ri))
        idx += 2

    n = len(s)

    # DP to determine if substring s[i..j] is a palindrome
    dp = [[False] * n for _ in range(n)]

    # DP to count palindromic substrings in s[i..j]
    count = [[0] * n for _ in range(n)]

    for i in range(n-1, -1, -1):
        for j in range(i, n):
            if i == j:
                dp[i][j] = True
                count[i][j] = 1
            else:
                dp[i][j] = s[i] == s[j] and dp[i+1][j-1]

                if dp[i][j]:
                    count[i][j] = count[i+1][j-1] + 1
                else:
                    count[i][j] = count[i+1][j-1]

    # Answer queries
    output = []
    for li, ri in queries:
        output.append(str(count[li-1][ri-1]))

    print(' '.join(output))

if __name__ == '__main__':
    main()
