import math

def solve():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    # Compute prefix products with gcd consideration
    prefix = [1] * n

    for i in range(n):
        prefix_product = (prefix[i-1] if i > 0 else 1) * a[i]

        # Divide by gcd to keep track of divisibility
        g = math.gcd(prefix_product, k)
        prefix[i] = (prefix_product // g) * g  # This keeps the product information

        # If prefix_product % k == 0, then we have all of k
        if prefix[i] == k:
            prefix[i] = k  # Mark this prefix as fully divisible by k

    # Count valid subarrays
    result = 0

    for i in range(n):
        # product from 0 to i is prefix[i]
        for j in range(i, n):
            if i == 0:
                # product from 0 to j is prefix[j]
                if j == n-1:
                    prod = prefix[j]
                else:
                    prod = prefix[j]
            else:
                # product from i to j is prefix[j] / prefix[i-1]
                if prefix[i-1] == k:
                    # Any product from i will be divisible by k
                    result += (n - j)
                    break
                else:
                    # Check divisibility
                    if prefix[j] % (prefix[i-1] * k) == 0:
                        result += (n - j)
                        break

    print(result)

solve()
