def is_valid(grid, n):
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '1':
                # Check if there's a left neighbor (same row)
                has_left = any(grid[i][k] == '1' for k in range(j))

                # Check if there's an upper neighbor (same column)
                has_upper = any(grid[k][j] == '1' for k in range(i))

                # Special case: (1, 1) is always invalid
                if i == 0 and j == 0:
                    return False

                # For cells in first row (i=0) we need a left neighbor
                if i == 0 and not has_left:
