def can_reach(target_sum):
    # Memoization cache: (min, max) -> set of reachable sums
    memo = {}

    # Helper function to find sum of elements in range [low, high]
    def get_sum(low, high, current_elements):
        total = 0
        for val in current_elements:
            if low <= val <= high:
                total += val
        return total

    # DFS with memoization
    def dfs(min_val, max_val, current_elements):
        if min_val > max_val:
            return None

        if (min_val, max_val) in memo:
            return memo[(min_val, max_val)].copy()

        # Base case: only one element
        if min_val == max_val:
            return {min_val}  # Just the one element

        mid = (min_val + max_val) // 2

        # Compute sums for left and right
        left_sum = get_sum(min_val, mid, current_elements)
        right_sum = get_sum(mid + 1, max_val, current_elements)

        # Recursive exploration
        left_sums = dfs(min_val, mid, current_elements)
        right_sums = dfs(mid + 1, max_val, current_elements)

        # Combine results
        reachable = set()
        for s in left_sums:
            reachable.add(s)
        for s in right_sums:
            reachable.add(s)

        memo[(min_val, max_val)] = reachable
        return reachable

    # Sort array for binary search
    a.sort()

    # Get reachable sums from initial state
    reachable = dfs(min(a), max(a), a)

    return target_sum in reachable

# Main function
t = int(input())
for _ in range(t):
    n, q = map(int, input().split())
    a = list(map(int, input().split()))

    for _ in range(q):
        s = int(input())
        print("Yes" if can_reach(s) else "No")
