def is_valid(matrix, n):
    """Check if the matrix can be formed by cannons"""
    for i in range(n):
        for j in range(n):
            # If there's a 1 at (i, j), check if both (i, 1) and (1, j) are 0
            if matrix[i][j] == '1':
                # Check if we can trace back from (i, j) to a cannon
                # Case 1: came from row cannon at (i, 1) moving right
                # Path: (i, 1) -> (i, 2) -> ... -> (i, j)
                path_valid_from_left = True
                for k in range(1, j):
                    if matrix[i][k] != '0':
                        path_valid_from_left = False
                        break
                # Case 2: came from column cannon at (1, j) moving down
                # Path: (1, j) -> (2, j) -> ... -> (i, j)
                path_valid_from_above = True
                for k in range(1, i):
                    if matrix[k][j] != '0':
                        path_valid_from_above = False
                        break

                # If either path is valid, continue
                if path_valid_from_left or path_valid_from_above:
                    continue
                else:
                    return False
    return True

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        matrix = []
        for _ in range(n):
            matrix.append(list(input().strip()))

        if is_valid(matrix, n):
            print("YES")
        else:
            print("NO")

