    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    result = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Mark elements as special
        is_special = [False] * n

        # For each possible subarray (start, end) where start < end
        for start in range(n):
            current_sum = a[start]

            for end in range(start + 1, n):
                current_sum += a[end]

                # If this sum exists in the array, mark all elements equal to it as special
                for i in range(n):
                    if a[i] == current_sum:
                        is_special[i] = True

        special_count = sum(is_special)
        result.append(str(special_count))

    sys.stdout.write("\n".join(result))

if __name__ == "__main__":
    solve()
