def tram_position(position, direction, time, s):
    """Return the position of the tram after given time"""

    # Time to reach endpoints
    time_to_s = (s - position) * t1 if direction == 1 else float('inf')
    time_to_0 = position * t1 if direction == -1 else float('inf')

    if time_to_s < time_to_0 and direction == 1:
        # Moving towards s
        if time <= time_to_s:
            return position + (time / t1)
        time -= time_to_s
        position = s
        direction = -1
    elif time_to_0 < time_to_s and direction == -1:
        # Moving towards 0
        if time <= time_to_0:
            return position - (time / t1)
        time -= time_to_0
        position = 0
        direction = 1

    # After reaching an endpoint, continue moving back
    # We need to handle multiple cycles

    while time > 0:
        if direction == 1:
            # From 0 to s
            if time <= s * t1:
                return position + (time / t1)
            time -= s * t1
            position = s
            direction = -1
        else:
            # From s to 0
            if time <= s * t1:
                return position - (time / t1)
            time -= s * t1
            position = 0
            direction = 1

    return position

def solve():
    s, x1, x2 = map(int, input().split())
    t1, t2 = map(int, input().split())
    p, d = map(int, input().split())

    # Calculate direct walk time
    walk_time = abs(x2 - x1) * t2
    min_time = walk_time

    # Check all possible meeting points
    for x in range(0, s + 1):
        # Time for Igor to walk from x1 to x
        time_to_meet = abs(x - x1) * t2

        # Where is the tram after time_to_meet?
        tram_pos = tram_position(p, d, time_to_meet, s)

        # If they meet at position x:
        if x == tram_pos:
            # Igor can ride the tram from x to x2
            time_to_x2 = abs(x2 - x) * t1
            min_time = min(min_time, time_to_meet + time_to_x2)

    print(min_time)

