import sys

def solve() -> None:
    """Solve the problem."""
    data = sys.stdin.read().strip().split()
    if not data:
        return

    s = data[0]
    t = data[1] if len(data) > 1 else ""

    # Check if need tree
    need_tree = False
    # Check if t has characters not in s
    s_chars = set(s)
    t_chars = set(t)
    for c in t_chars:
        if c not in s_chars:
            need_tree = True
            break

    # Check if we need both structures
    need_both = False
    if len(t) < len(s) and need_tree:
        need_both = True

    # Check if we can use automaton only
    automaton = False
    if len(t) <= len(s) and not need_tree:
        automaton = True

    # Check if we can use array only
    array = False
    if len(t) >= len(s) and not need_tree:
        array = True

    # Determine the answer
    if need_tree:
        print("need tree")
    elif automaton:
        print("automaton")
