    A = []

    for i in range(1, n + 1):
        row = []
        line = data[i].strip()
        for ch in line:
            row.append(int(ch))
        A.append(row)

    # Precompute incoming edges for each vertex
    incoming = [set() for _ in range(n)]
    for a in range(n):
        for b in range(n):
            if b != a and A[b][a] == 1:
                incoming[a].add(b)

    # Try each pair (a, b) with A[a][b] = 1
    for a in range(n):
        for b in range(n):
            if b != a and A[a][b] == 1:
                # Check if b has an edge to any incoming neighbor of a
                for c in incoming[a]:
                    if A[b][c] == 1:
                        print(f"{a+1} {b+1} {c+1}")
                        return

    print("-1")

