def construct_pattern(n, m):
    # Create the cyclic pattern for each row
    base = "aeiou"
    pattern = ""
    for row in range(n):
        # Row i is base shifted left by row positions
        shifted = base[row:] + base[:row]
        # Repeat to fill the row to length m
        pattern += shifted * (m // len(base) + 1)

    # Trim to exactly length k
    return pattern[:k]

