import sys

def is_palindrome(s, l, r):
    while l < r:
        if s[l] != s[r]:
            return False
        l += 1
        r -= 1
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    s = data[0]
    q = int(data[1])
    queries = []
    idx = 2

    # Precompute all palindromic substrings
    palindromes = []
    n = len(s)

    # Count single-character palindromes
    for i in range(n):
        palindromes.append((i + 1, i + 1))  # 1-indexed

    # Count length 2 palindromes
    for i in range(n - 1):
        if s[i] == s[i + 1]:
            palindromes.append((i + 1, i + 2))

    # Count length 3 palindromes
    for i in range(n - 2):
        if s[i] == s[i + 2]:
            palindromes.append((i + 1, i + 3))

    # Count longer palindromes
    for i in range(n):
        # Expand around center for odd length
        left, right = i, i
        while left >= 0 and right < n and s[left] == s[right]:
            if right - left + 1 > 3:
                palindromes.append((left + 1, right + 1))
            left -= 1
            right += 1

    # Handle even length palindromes separately
    for i in range(n - 1):
        left, right = i, i + 1
        while left >= 0 and right < n and s[left] == s[right]:
            if right - left + 1 > 3:
                palindromes.append((left + 1, right + 1))
            left -= 1
            right += 1

    # Answer queries
    out_lines = []
    for _ in range(q):
        l = int(data[idx])
        r = int(data[idx + 1])
        idx += 2

        count = 0
        for (start, end) in palindromes:
            if l <= start <= end <= r:
                count += 1

        out_lines.append(str(count))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

