n, s, k = map(int, input().split())
r = list(map(int, input().split()))
c = input().strip()

INF = float('inf')

# dp[pos][last_color][last_count][eaten] = minimum time
# pos: 1-indexed, 1..n
# last_color: 0, 1, 2 for R, G, B
# last_count: 1..n
# eaten: 0..k

dp = [[[[-1 for _ in range(k+1)] for _ in range(n+1)] for _ in range(3)] for _ in range(n+1)]

# Initialize: start at position s with no previous state
# Use -1 for color to indicate no previous color
for i in range(n+1):
    for j in range(3):
        for eaten in range(k+1):
            # If we haven't eaten anything, we just wait
            dp[s][j][0][eaten] = 0

# Convert colors to 0, 1, 2 for easier indexing
for i in range(n):
    if c[i] == 'R':
        c[i] = 0
    elif c[i] == 'G':
        c[i] = 1
    elif c[i] == 'B':
        c[i] = 2

# dp[pos][last_color][last_count][eaten] = min_time
# Iterate over all states
for pos in range(1, n+1):
    for last_color in range(3):
        for last_count in range(1, n+1):  # max count is 50
            for eaten in range(k+1):
                if dp[pos][last_color][last_count][eaten] == -1:
                    continue

                # Move to position pos-1
                if pos-1 >= 1:
                    dp[pos-1][last_color][last_count][eaten] = min(
                        dp[pos-1][last_color][last_count][eaten],
                        dp[pos][last_color][last_count][eaten] + 1
                    )

                # Move to position pos+1
                if pos+1 <= n:
                    dp[pos+1][last_color][last_count][eaten] = min(
                        dp[pos+1][last_color][last_count][eaten],
                        dp[pos][last_color][last_count][eaten] + 1
                    )

                # Eat candies at current position
                if eaten + r[pos-1] >= k:
                    dp[pos][last_color][last_count][eaten + r[pos-1]] = min(
                        dp[pos][last_color][last_count][eaten + r[pos-1]],
                        dp[pos][last_color][last_count][eaten]
                    )
                elif last_color != c[pos-1] and last_count < r[pos-1]:
                    # We can eat candies at this position
                    dp[pos][c[pos-1]][r[pos-1]][eaten + r[pos-1]] = min(
                        dp[pos][c[pos-1]][r[pos-1]][eaten + r[pos-1]],
                        dp[pos][last_color][last_count][eaten]
                    )

# Find the minimum time to eat at least k candies
min_time = INF
for i in range(n+1):
    for last_color in range(3):
        for last_count in range(1, n+1):
            for eaten in range(k+1):
                if eaten >= k:
                    min_time = min(min_time, dp[i][last_color][last_count][eaten])

print(min_time if min_time != INF else -1
"}

